#!/usr/bin/env python3
"""Temporary init-like wrapper: reap adopted descendants; preserve command exit."""
import ctypes,errno,os,signal,subprocess,sys
if len(sys.argv)<2:
 print('usage: child-subreaper.py command [args...]',file=sys.stderr);sys.exit(2)
libc=ctypes.CDLL(None,use_errno=True)
if libc.prctl(36,1,0,0,0)!=0: # Linux PR_SET_CHILD_SUBREAPER
 e=ctypes.get_errno();raise OSError(e,os.strerror(e))
child=subprocess.Popen(sys.argv[1:],start_new_session=True)
def forward(sig,frame):
 try:os.killpg(child.pid,sig)
 except ProcessLookupError:pass
for sig in [signal.SIGINT,signal.SIGTERM]:signal.signal(sig,forward)
root_status=None;adopted=0
while True:
 try:pid,status=os.waitpid(-1,0)
 except InterruptedError:continue
 except ChildProcessError:break
 if pid==child.pid:root_status=status
 else:adopted+=1
if root_status is None:
 print('[subreaper] missing child exit status',file=sys.stderr);sys.exit(125)
code=os.waitstatus_to_exitcode(root_status)
print(f'[subreaper] root={child.pid} exit={code} adopted_reaped={adopted}',file=sys.stderr)
sys.exit(code if code>=0 else 128-code)

