with (root/('signal-'+label+'.log')).open('w') as f:
 p=subprocess.Popen(command,cwd='/workspace/Jovie',env=env,stdout=f,stderr=subprocess.STDOUT)
 while p.poll() is None:
  for d in set(pathlib.Path('/tmp').glob('affected-process-group-*'))-before:
   try:pid=int((d/'grandchild.pid').read_text())
   except (FileNotFoundError,ValueError):continue
   key=str(pid)
   try:
    raw=pathlib.Path('/proc/'+key+'/stat').read_text();fields=raw[raw.rfind(')')+2:].split();state={'state':fields[0],'ppid':int(fields[1])}
   except FileNotFoundError:state={'state':'ABSENT','ppid':None}
   rows=observations.setdefault(key,[])
   if not rows or any(rows[-1].get(k)!=v for k,v in state.items()):rows.append({'elapsedSeconds':round(time.monotonic()-start,3),**state})
  if time.monotonic()-start>40:
   p.terminate();raise RuntimeError('observer bounded timeout')
